void HandleNavigationCommit(RenderFrameHostImpl* rfh,
                             const FrameHostMsg_DidCommitProvisionalLoad_Params& params,
                             bool is_in_page,
                             bool replace_entry,
                             NavigationHandleImpl* handle) {
  NavigationEntry* entry = nullptr;

  if (is_in_page) {
    // Clone the current entry if this is an in-page navigation.
    entry = CloneNavigationEntry(rfh->GetNavigationEntry());
  } else {
    // Check for a matching pending entry.
    if (handle && handle->HasPendingEntry()) {
      entry = handle->TakePendingEntry();
    }

    if (!entry) {
      // Create a new entry based on navigation parameters.
      entry = CreateNavigationEntryFromParams(params);
    }

    // Update virtual URL and session history.
    UpdateVirtualURL(entry, params.virtual_url);
    UpdateSessionHistory(rfh, entry, replace_entry);
  }

  // Insert or replace the entry in navigation history.
  if (replace_entry) {
    rfh->ReplaceNavigationEntry(entry);
  } else {
    rfh->InsertNavigationEntry(entry);
  }
}

