void HandleNavigationCommit(
    RenderFrameHostImpl* rfh,
    const FrameHostMsg_DidCommitProvisionalLoad_Params& params,
    bool is_in_page,
    bool replace_entry,
    NavigationHandleImpl* handle) {
  if (is_in_page) {
    // Clone the current entry for in-page navigation.
    NavigationEntryImpl* current_entry = rfh->GetNavigationEntry();
    if (current_entry) {
      NavigationEntryImpl* cloned_entry = current_entry->Clone();
      // Apply in-page navigation updates to cloned_entry if needed.
      rfh->SetNavigationEntry(cloned_entry);
    }
  }

  // Check if a pending entry exists that matches the navigation handle.
  NavigationEntryImpl* pending_entry = rfh->GetPendingNavigationEntry();
  if (pending_entry && pending_entry->GetNavigationHandle() == handle) {
    // Update or use the pending entry based on navigation parameters.
    pending_entry->SetURL(params.url);
    pending_entry->SetTitle(params.title);
    rfh->CommitPendingNavigationEntry();
  } else {
    // Create a new navigation entry.
    NavigationEntryImpl* new_entry = new NavigationEntryImpl();
    new_entry->SetURL(params.url);
    new_entry->SetTitle(params.title);
    new_entry->SetPageId(params.page_id);
    new_entry->SetNavigationHandle(handle);

    // Update virtual URL if necessary.
    if (!params.virtual_url.is_empty())
      new_entry->SetVirtualURL(params.virtual_url);

    // Update session history based on the navigation state.
    if (replace_entry) {
      rfh->ReplaceNavigationEntry(new_entry);
    } else {
      rfh->InsertNavigationEntry(new_entry);
    }
  }
}

