void HandleNavigationCommit(
    RenderFrameHostImpl* rfh,
    const FrameHostMsg_DidCommitProvisionalLoad_Params& params,
    bool is_in_page,
    bool replace_entry,
    NavigationHandleImpl* handle) {
  // Check if this is an in-page navigation and clone the current entry if so
  if (is_in_page) {
    // Clone the current session history entry
    SessionHistoryEntry* entry = CloneCurrentEntry(rfh);
    if (entry) {
      // Update the entry with the new navigation details
      UpdateEntryWithNavigationDetails(entry, params);
    }
    return;
  }

  // Check if there's a pending entry that matches the navigation handle
  SessionHistoryEntry* pending_entry = FindPendingEntry(handle);
  if (pending_entry) {
    // Update the existing entry with the new navigation parameters
    pending_entry->url = params.url;
    pending_entry->title = params.title;
    pending_entry->timestamp = params.timestamp;
    return;
  }

  // Create a new session history entry
  SessionHistoryEntry* new_entry = CreateNewEntry(params);

  // Set new entry properties based on navigation parameters
  new_entry->url = params.url;
  new_entry->title = params.title;
  new_entry->timestamp = params.timestamp;

  // Handle updating the virtual URL
  UpdateVirtualURL(rfh, params.url);

  // Insert or replace the entry in the navigation history
  if (replace_entry) {
    ReplaceSessionHistoryEntry(rfh, new_entry);
  } else {
    InsertSessionHistoryEntry(rfh, new_entry);
  }
}
